region:
void ContentDigester::compressBlock(const std::uint8_t* block)
{
    // 消息调度：W[0..15] 直接取自分组（大端），W[16..63] 按 σ0/σ1 扩展（§6.2.2）。
    std::uint32_t w[64];
    for (int t = 0; t < 16; ++t) {
        w[t] = loadBE32(block + 4 * t);
    }
    for (int t = 16; t < 64; ++t) {
        const std::uint32_t s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >> 3);
        const std::uint32_t s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >> 10);
        w[t] = w[t - 16] + s0 + w[t - 7] + s1;
    }

    // 64 轮压缩（工作变量 a..h；函数 Ch/Maj/Σ0/Σ1 见 FIPS §4.1.2）。
    std::uint32_t a = state_[0], b = state_[1], c = state_[2], d = state_[3];
    std::uint32_t e = state_[4], f = state_[5], g = state_[6], h = state_[7];
    for (int t = 0; t < 64; ++t) {
        const std::uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
        const std::uint32_t ch = (e & f) ^ (~e & g);
        const std::uint32_t t1 = h + S1 + ch + kSha256K[static_cast<std::size_t>(t)] + w[t];
        const std::uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
        const std::uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        const std::uint32_t t2 = S0 + maj;
        h = g; g = f; f = e;
        e = d + t1;
        d = c; c = b; b = a;
        a = t1 + t2;
    }

    // 链接变量累加（中途值寄存于工作变量，轮毕回加——FIPS §6.2.2 第 14 步）。
    state_[0] += a; state_[1] += b; state_[2] += c; state_[3] += d;
    state_[4] += e; state_[5] += f; state_[6] += g; state_[7] += h;
}

bool strictUtf8Check(std::string_view bytes, std::size_t* failIndex)
{
    std::uint32_t state = 0;   // 起始＝接受态
    for (std::size_t i = 0; i < bytes.size(); ++i) {
        const std::uint8_t b = static_cast<std::uint8_t>(bytes[i]);
        state = kUtf8Dfa[256 + state + kUtf8Dfa[b]];
        if (state == kUtf8Reject) {
            *failIndex = i;
            return false;
        }
    }
    // 悬空多字节序列（文档截断在多字节字符中段）同样非法——终态非接受。
    if (state != 0) {
        *failIndex = bytes.size();
        return false;
    }
    return true;
}

IoResult<IoString> canonicalizeJson(const JsonDocument& doc, const JsonWriteOptions& options)
{
    IoResult<IoString> out;
    try {
        // canonical 序列化（键序/版面/数值形态恒定——§5.9.3）；非有限实
        // 数经 emitCanonicalValue 拒绝（错误原样上抛——错误轨道单一权威）。
        IoString bytes;
        const JsonShape* shape =
            (options.profile != nullptr) ? &options.profile->rootShape : nullptr;
        if (const IoResult<void> r = emitCanonicalValue(bytes, doc.root, shape, options, 0); !r) {
            out.error = r.error;
            return out;
        }
        // 根级换行收尾：canonical 文件形态以 LF 结束（POSIX 文本惯例——
        // 与写出器同一实现面，digest 与 write 字节必然一致）。
        bytes.append(kLf);
        out.value = std::move(bytes);
        return out;
    } catch (const std::exception& e) {
        out.error = IoError{IoErrorCode::FormatInternal, {},
                            std::string("json canonicalize: ") + e.what()};
        return out;
    } catch (...) {
        out.error = IoError{IoErrorCode::FormatInternal, {},
                            "json canonicalize: unknown exception"};
        return out;
    }
}

rw::math::Vector3D<double> orientBoxPoint(const RegionBox& box,
                                         const rw::math::Vector3D<double>& p)
{
    const auto& r = box.orientationInBase;
    if (r == rw::math::Rotation3D<double>(1,0,0,0,1,0,0,0,1)) { return p; }
    const auto d = p - box.center;
    return {box.center[0] + r(0,0)*d[0] + r(0,1)*d[1] + r(0,2)*d[2],
            box.center[1] + r(1,0)*d[0] + r(1,1)*d[1] + r(1,2)*d[2],
            box.center[2] + r(2,0)*d[0] + r(2,1)*d[1] + r(2,2)*d[2]};
}

rw::math::Rotation3D<double> orientSampleRotation(const rw::math::Rotation3D<double>& a,
                                                 const rw::math::Rotation3D<double>& b)
{
    rw::math::Rotation3D<double> result(1,0,0,0,1,0,0,0,1);
    for (int i=0; i<3; ++i) for (int j=0; j<3; ++j) {
        result(i,j)=a(i,0)*b(0,j)+a(i,1)*b(1,j)+a(i,2)*b(2,j);
    }
    return result;
}

rw::math::Transform3D<double> poseFromDirectionRoll(
    const rw::math::Vector3D<double>& direction, double roll,
    const rw::math::Vector3D<double>& position)
{
    // 第一步：工具 z 轴（+Z）到方向 d 的最小旋转的九个矩阵元（Rodrigues
    // 轴角公式直写——轴＝ẑ×d、角＝atan2(|ẑ×d|, ẑ·d)；双退化分支：d≈+ẑ
    // 恒等、d≈−ẑ 绕 x 半周。与产品 Fk 路径无共享代码的独立小实现，仅
    // 姿态组装用；rw 旋转类型的外联符号（默认构造/operator*）全程规避
    // ——冒烟模式不链 rw 库，Ik.hpp identityTransform3D 同款纪律）。
    const double dx = direction[0];
    const double dy = direction[1];
    const double dz = direction[2];
    const double cx = -dy;             // ẑ×d 的 x 分量（ẑ＝(0,0,1)）
    const double cy = dx;              // ẑ×d 的 y 分量
    const double cz = 0.0;             // ẑ×d 的 z 分量
    const double crossNorm = std::sqrt(cx * cx + cy * cy + cz * cz);
    const double dot = dz;             // ẑ·d＝d 的 z 分量

    double m00 = 0.0; double m01 = 0.0; double m02 = 0.0;
    double m10 = 0.0; double m11 = 0.0; double m12 = 0.0;
    double m20 = 0.0; double m21 = 0.0; double m22 = 0.0;
    if (crossNorm > 1e-12) {
        // 常规分支：Rodrigues 公式展开（R＝I＋sinθ·[axis]×＋(1−cosθ)·
        // [axis]×²——按分量直写）。
        const double ax = cx / crossNorm;
        const double ay = cy / crossNorm;
        const double az = cz / crossNorm;
        const double angle = std::atan2(crossNorm, dot);  // atan2 比 acos 数值稳定
        const double c = std::cos(angle);
        const double s = std::sin(angle);
        const double t = 1.0 - c;
        m00 = t * ax * ax + c;       m01 = t * ax * ay - s * az; m02 = t * ax * az + s * ay;
        m10 = t * ax * ay + s * az;  m11 = t * ay * ay + c;       m12 = t * ay * az - s * ax;
        m20 = t * ax * az - s * ay;  m21 = t * ay * az + s * ax;  m22 = t * az * az + c;
    } else if (dot > 0.0) {
        // 退化分支 1：d≈+ẑ（夹角 0）——恒等旋转。
        m00 = 1.0; m01 = 0.0; m02 = 0.0;
        m10 = 0.0; m11 = 1.0; m12 = 0.0;
        m20 = 0.0; m21 = 0.0; m22 = 1.0;
    } else {
        // 退化分支 2：d≈−ẑ（夹角 π）——绕 x 轴半周（任一正交半周皆可，
        // 黄金锁定取 x 轴分支）。
        m00 = 1.0; m01 = 0.0; m02 = 0.0;
        m10 = 0.0; m11 = -1.0; m12 = 0.0;
        m20 = 0.0; m21 = 0.0; m22 = -1.0;
    }

    // 第二步：绕局部 z 轴转 roll（工具滚转）——R＝R_dir·Rz(roll)。
    // 手写三阶矩阵积：rw 的 Rotation3D::operator*（multiply）是外联符号，
    // 冒烟模式（不链 rw 库）不可解析。列组合展开：R·Rz 的第 0 列＝cr·
    // R_dir 列 0＋sr·R_dir 列 1、第 1 列＝cr·R_dir 列 1−sr·R_dir 列 0、
    // 第 2 列＝R_dir 列 2（Rz 右乘只混前两列）。
    const double cr = std::cos(roll);
    const double sr = std::sin(roll);
    const rw::math::Rotation3D<double> rRoll(
        m00 * cr + m01 * sr, m01 * cr - m00 * sr, m02,
        m10 * cr + m11 * sr, m11 * cr - m10 * sr, m12,
        m20 * cr + m21 * sr, m21 * cr - m20 * sr, m22);
    return rw::math::Transform3D<double>(position, rRoll);
}

void validateBoxOrientation(const rw::math::Rotation3D<double>& r)
{
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            double dot = 0;
            for (int k = 0; k < 3; ++k) {
                if (!std::isfinite(r(k, i))) {
                    throw std::invalid_argument("区域orientationInBase非有限：请修正参考系旋转");
                }
                dot += r(k, i) * r(k, j);
            }
            if (std::fabs(dot - (i == j ? 1.0 : 0.0)) > 1e-9) {
                throw std::invalid_argument("区域orientationInBase非正交：请使用刚体参考系");
            }
        }
    }
    const double det = r(0,0)*(r(1,1)*r(2,2)-r(1,2)*r(2,1))
        - r(0,1)*(r(1,0)*r(2,2)-r(1,2)*r(2,0))
        + r(0,2)*(r(1,0)*r(2,1)-r(1,1)*r(2,0));
    if (std::fabs(det - 1.0) > 1e-9) {
        throw std::invalid_argument("区域orientationInBase不是右手旋转：请修正参考系");
    }
}

generateRandomPositions(const RegionBox& box, std::uint32_t count, std::uint64_t seed)
{
    validateBoxOrientation(box.orientationInBase);
    std::vector<rw::math::Vector3D<double>> out;
    out.reserve(count);
    // 种子派生确定性序列（黄金锁定）：第 k 个样本状态＝(seed, k) 完整
    // 64 位混合（streamSeedFor——KIN-P5/审查 A06：旧"seed·2³²＋k"丢弃
    // seed 高 32 位；换用混合派生属算法语义变更，样本集身份经 IRDSSID
    // codec 版本 1→2 同步升级——见 sampleSetIdentity 注），逐轴连续派生
    // x→y→z。
    for (std::uint32_t k = 0; k < count; ++k) {
        std::uint64_t state = streamSeedFor(seed, k);
        const double u0 = unitFromU64(splitmix64(state));
        const double u1 = unitFromU64(splitmix64(state));
        const double u2 = unitFromU64(splitmix64(state));
        out.push_back(orientBoxPoint(box, {box.center[0] - box.size[0] / 2.0 + u0 * box.size[0],
                         box.center[1] - box.size[1] / 2.0 + u1 * box.size[1],
                         box.center[2] - box.size[2] / 2.0 + u2 * box.size[2]}));
    }
    return out;
}

generateGridPositions(const RegionBox& box, const std::array<std::uint32_t, 3>& counts)
{
    validateBoxOrientation(box.orientationInBase);
    std::vector<rw::math::Vector3D<double>> out;
    // 零样本判定前置：任一轴计数 0 → 乘积 0（I-REQ-6 零样本场景——空集
    // 合法，评估面判 DataInsufficient；此处不拒）。★ 审查 G19 防御：乘前
    // 回卷检查（病态大计数三轴乘积模 2⁶⁴ 回卷为小值→reserve/枚举失真
    // ——拒绝而非静默；与 plannedPositionSampleCount 防御同源）。
    constexpr std::uint64_t kU64Max = std::numeric_limits<std::uint64_t>::max();
    std::uint64_t product = 1U;
    for (const std::uint32_t c : counts) {
        if (c != 0U && product > kU64Max / c) {
            throw std::invalid_argument(
                "generateGridPositions: 区域网格计数乘积超出 u64（回卷防护"
                "——计划计数损坏）");
        }
        product *= c;
    }
    if (product == 0) {
        return out;
    }
    out.reserve(static_cast<std::size_t>(product));

    // 盒端点（基座系 {B}，单位 m）。
    const double minX = box.center[0] - box.size[0] / 2.0;
    const double minY = box.center[1] - box.size[1] / 2.0;
    const double minZ = box.center[2] - box.size[2] / 2.0;

    // 体心规则（黄金锁定）：格心＝min＋(k＋0.5)·格宽；枚举序＝x 最慢、
    // z 最快（index＝(ix·counts[1]＋iy)·counts[2]＋iz——登记序）。
    for (std::uint32_t ix = 0; ix < counts[0]; ++ix) {
        const double x = minX + (static_cast<double>(ix) + 0.5)
            * (box.size[0] / static_cast<double>(counts[0]));
        for (std::uint32_t iy = 0; iy < counts[1]; ++iy) {
            const double y = minY + (static_cast<double>(iy) + 0.5)
                * (box.size[1] / static_cast<double>(counts[1]));
            for (std::uint32_t iz = 0; iz < counts[2]; ++iz) {
                const double z = minZ + (static_cast<double>(iz) + 0.5)
                    * (box.size[2] / static_cast<double>(counts[2]));
                out.push_back(orientBoxPoint(box, {x, y, z}));
            }
        }
    }
    return out;
}

std::vector<rw::math::Vector3D<double>> generateDirections(std::uint32_t count)
{
    std::vector<rw::math::Vector3D<double>> out;
    out.reserve(count);
    // 斐波那契螺旋（黄金锁定）：z_j＝1−(2j＋1)/N、r_j＝√(1−z_j²)、
    // φ_j＝j·黄金角——球面近似均匀方向集；N=1 退化 z=0、r=1、φ=0＝+X。
    for (std::uint32_t j = 0; j < count; ++j) {
        const double n = static_cast<double>(count);
        const double z = 1.0 - (2.0 * static_cast<double>(j) + 1.0) / n;
        const double r = std::sqrt(std::max(0.0, 1.0 - z * z));  // 下截断防浮点负
        const double phi = static_cast<double>(j) * kFibonacciGoldenAngle;
        out.emplace_back(r * std::cos(phi), r * std::sin(phi), z);
    }
    return out;
}

inline std::uint64_t splitmix64(std::uint64_t& state)
{
    state += 0x9E3779B97F4A7C15ull;
    std::uint64_t z = state;
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ull;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBull;
    return z ^ (z >> 31);
}

inline std::uint64_t streamSeedFor(std::uint64_t seed, std::uint64_t index)
{
    std::uint64_t s = seed;
    const std::uint64_t a = splitmix64(s);
    std::uint64_t t = index ^ 0x9E3779B97F4A7C15ull;
    const std::uint64_t b = splitmix64(t);
    std::uint64_t u = a ^ b;
    return splitmix64(u);
}

rw::math::Rotation3D<double> transposeOf(const rw::math::Rotation3D<double>& r)
{
    return rw::math::Rotation3D<double>(
        r(0,0),r(1,0),r(2,0), r(0,1),r(1,1),r(2,1), r(0,2),r(1,2),r(2,2));
}

std::array<double, 3> zyxEulerAngles(const rw::math::Rotation3D<double>& r)
{
    constexpr double kGimbalEpsilon = 1e-5;
    constexpr double kHalfPi = 1.57079632679489661923;
    const double cosPitch = std::sqrt(r(0, 0) * r(0, 0) + r(1, 0) * r(1, 0));
    const double sinPitch = -r(2, 0);
    std::array<double, 3> a{}; // roll(X), pitch(Y), yaw(Z)，单位 rad
    if (cosPitch < kGimbalEpsilon) {
        // 万向锁时固定 roll=0，yaw 从剩余矩阵项确定（两分支同号——见上注）。
        a[0] = 0.0;
        a[1] = sinPitch < 0.0 ? -kHalfPi : kHalfPi;
        a[2] = -std::atan2(r(0, 1), r(1, 1));
    } else {
        a[1] = std::atan2(sinPitch, cosPitch);
        a[0] = std::atan2(r(2, 1), r(2, 2));
        a[2] = std::atan2(r(1, 0), r(0, 0));
    }
    return a;
}

Eigen::Matrix<double, 6, 1> poseError(const rw::math::Transform3D<double>& target,
                                      const rw::math::Transform3D<double>& tcpInBase,
                                      double& posResidualOut,
                                      double& oriResidualOut)
{
    Eigen::Matrix<double, 6, 1> e;
    // 位置误差（m——基座系逐分量差后取模）。
    const double dx = target.P()[0] - tcpInBase.P()[0];
    const double dy = target.P()[1] - tcpInBase.P()[1];
    const double dz = target.P()[2] - tcpInBase.P()[2];
    e(0) = dx;
    e(1) = dy;
    e(2) = dz;
    posResidualOut = std::sqrt(dx * dx + dy * dy + dz * dz);

    // 姿态误差（rad）：R_err＝R_target·R_tcpᵀ 的旋转向量——模长即转角。
    Eigen::Matrix3d rTcp;
    Eigen::Matrix3d rTarget;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            rTcp(i, j) = tcpInBase.R()(static_cast<std::size_t>(i),
                                       static_cast<std::size_t>(j));
            rTarget(i, j) = target.R()(static_cast<std::size_t>(i),
                                       static_cast<std::size_t>(j));
        }
    }
    const Eigen::AngleAxisd aa(rTarget * rTcp.transpose());
    const Eigen::Vector3d rotvec = aa.axis() * aa.angle();
    e(3) = rotvec(0);
    e(4) = rotvec(1);
    e(5) = rotvec(2);
    oriResidualOut = aa.angle() < 0.0 ? -aa.angle() : aa.angle();
    return e;
}

Eigen::Matrix<double,6,1> constrainedPoseError(
    const rw::math::Transform3D<double>& target,
    const rw::math::Transform3D<double>& actual,
    const TaskPoseConstraint& constraint,double& posResidual,double& oriResidual)
{
    const auto& rr=constraint.referenceInBase;
    const auto refT=transposeOf(rr);
    const auto desired=constraint.allowToolRoll
        ?nearestToolRollTarget(target.R(),actual.R(),constraint.rollRange):target.R();
    const auto targetRpy=zyxEulerAngles(composeOf(refT,desired));
    const auto actualRpy=zyxEulerAngles(composeOf(refT,actual.R()));
    const auto dp=target.P()-actual.P();
    Eigen::Matrix<double,6,1> e=Eigen::Matrix<double,6,1>::Zero();
    double p2=0.0,r2=0.0;
    for(int i=0;i<3;++i) {
        if(constraint.constrainedDof[static_cast<std::size_t>(i)]) {
            e(i)=rr(0,i)*dp[0]+rr(1,i)*dp[1]+rr(2,i)*dp[2];
            p2+=e(i)*e(i);
        }
        if(constraint.constrainedDof[static_cast<std::size_t>(3+i)]) {
            e(3+i)=wrapAngle(targetRpy[static_cast<std::size_t>(i)]
                            -actualRpy[static_cast<std::size_t>(i)]);
            r2+=e(3+i)*e(3+i);
        }
    }
    posResidual=std::sqrt(p2);oriResidual=std::sqrt(r2);
    return e;
}

std::optional<Eigen::VectorXd> constrainedDampedLeastSquaresStep(
    const IkRequest& request,const std::vector<double>& q,
    const Eigen::Matrix<double,6,1>& e,std::string& failure)
{
    constexpr double kDifferenceStep=1e-7;
    const auto dof=q.size();
    Eigen::MatrixXd j=Eigen::MatrixXd::Zero(6,static_cast<Eigen::Index>(dof));
    const FkEvaluator fk;
    for(std::size_t column=0;column<dof;++column) {
        auto plus=q,minus=q;
        plus[column]+=kDifferenceStep;minus[column]-=kDifferenceStep;
        const auto fp=fk.evaluate(*request.modelView,request.tcp,plus);
        const auto fm=fk.evaluate(*request.modelView,request.tcp,minus);
        if(!fp.ok()||!fm.ok()) {
            failure="约束Jacobian差分FK失败，轴"+std::to_string(column)+": "
                +(!fp.ok()?fp.error().detail:fm.error().detail);
            return std::nullopt;
        }
        double unusedPosition=0.0,unusedOrientation=0.0;
        const auto ep=constrainedPoseError(request.targetInBase,fp.get().tcpInBase,
            *request.taskConstraint,unusedPosition,unusedOrientation);
        const auto em=constrainedPoseError(request.targetInBase,fm.get().tcpInBase,
            *request.taskConstraint,unusedPosition,unusedOrientation);
        for(int row=0;row<6;++row) {
            const double difference=row>=3?wrapAngle(ep(row)-em(row)):ep(row)-em(row);
            j(row,static_cast<Eigen::Index>(column))=-difference/(2.0*kDifferenceStep);
        }
    }
    Eigen::MatrixXd normal=j*j.transpose();
    const double lambda2=kIkDampingLambda*kIkDampingLambda;
    for(int i=0;i<6;++i) normal(i,i)+=lambda2;
    return Eigen::VectorXd(j.transpose()*normal.llt().solve(e));
}

Eigen::VectorXd dampedLeastSquaresStep(const std::vector<double>& jacobianRowMajor,
                                       std::size_t dof,
                                       std::size_t taskDim,
                                       const Eigen::VectorXd& e)
{
    Eigen::MatrixXd J(static_cast<Eigen::Index>(taskDim),
                      static_cast<Eigen::Index>(dof));
    for (std::size_t r = 0; r < taskDim; ++r) {
        for (std::size_t c = 0; c < dof; ++c) {
            J(static_cast<Eigen::Index>(r), static_cast<Eigen::Index>(c)) =
                jacobianRowMajor[r * dof + c];
        }
    }
    // 正规方程矩阵 A＝JₜJₜᵀ＋λ²I_m（m×m 对称正定——λ>0 保证可逆；LLT
    // 单线程固定算法——确定性）。
    Eigen::MatrixXd A = J * J.transpose();
    const double lambda2 = kIkDampingLambda * kIkDampingLambda;
    for (Eigen::Index i = 0; i < static_cast<Eigen::Index>(taskDim); ++i) {
        A(i, i) += lambda2;
    }
    const Eigen::VectorXd x = A.llt().solve(e);
    return J.transpose() * x;
}

std::vector<std::vector<double>> makeInitialValues(InitialValueStrategy strategy,
                                                   std::uint32_t count,
                                                   std::uint64_t seed,
                                                   const std::vector<JointInterval>& intervals,
                                                   const std::vector<double>& referenceQ)
{
    std::vector<std::vector<double>> out;
    switch (strategy) {
    case InitialValueStrategy::ReferenceQ: {
        // 单初值＝显式参考构型（D-KIN-4 同源输入——初值与排序参考一致）。
        out.push_back(referenceQ);
        break;
    }
    case InitialValueStrategy::SeededRandom: {
        // seed 派生确定性序列：第 k 个初值状态＝(seed, k) 完整 64 位混合
        // （streamSeedFor——KIN-P5/审查 A06：旧"seed·2³²＋k"在模 2⁶⁴
        // 算术下丢弃 seed 高 32 位，不同高位种子假借同序列；混合派生后
        // 逐轴 u_k,i∈[0,1)（splitmix64 按轴序连续派生——同 seed 同矩阵）。
        out.reserve(count);
        for (std::uint32_t k = 0; k < count; ++k) {
            std::uint64_t state = streamSeedFor(seed, k);  // 初值序入混合
            std::vector<double> q;
            q.reserve(intervals.size());
            for (const auto& itv : intervals) {
                double lo = 0.0;
                double hi = 0.0;
                axisRange(itv, lo, hi);
                q.push_back(lo + unitFromU64(splitmix64(state)) * (hi - lo));
            }
            out.push_back(std::move(q));
        }
        break;
    }
    case InitialValueStrategy::JointGrid: {
        // 限位空间均分：t_k＝k/(count−1)（count=1 → 中点 0.5）；沿评价
        // 区间对角线取点——不做自由度组合展开（登记随卡 §14.6 v0.4）。
        const std::uint32_t n = count == 0U ? 1U : count;
        out.reserve(n);
        for (std::uint32_t k = 0; k < n; ++k) {
            const double t = (n == 1U) ? 0.5
                                       : static_cast<double>(k)
                                             / static_cast<double>(n - 1U);
            std::vector<double> q;
            q.reserve(intervals.size());
            for (const auto& itv : intervals) {
                double lo = 0.0;
                double hi = 0.0;
                axisRange(itv, lo, hi);
                q.push_back(lo + t * (hi - lo));
            }
            out.push_back(std::move(q));
        }
        break;
    }
    }
    return out;
}

rw::math::Vector3D<double> rotVec(const rw::math::Rotation3D<double>& r,
                                 const rw::math::Vector3D<double>& v)
{
    return rw::math::Vector3D<double>(
        r(0, 0) * v[0] + r(0, 1) * v[1] + r(0, 2) * v[2],
        r(1, 0) * v[0] + r(1, 1) * v[1] + r(1, 2) * v[2],
        r(2, 0) * v[0] + r(2, 1) * v[1] + r(2, 2) * v[2]);
}

rw::math::Rotation3D<double> rotMul(const rw::math::Rotation3D<double>& ra,
                                    const rw::math::Rotation3D<double>& rb)
{
    rw::math::Rotation3D<double> out;
    for (std::size_t i = 0; i < 3; ++i) {
        for (std::size_t j = 0; j < 3; ++j) {
            double s = 0.0;
            for (std::size_t k = 0; k < 3; ++k) { s += ra(i, k) * rb(k, j); }
            out(i, j) = s;
        }
    }
    return out;
}

rw::math::Transform3D<double> transformMul(const rw::math::Transform3D<double>& ta,
                                           const rw::math::Transform3D<double>& tb)
{
    const rw::math::Rotation3D<double> r = rotMul(ta.R(), tb.R());
    const rw::math::Vector3D<double> pb = tb.P();
    const rw::math::Vector3D<double> p = rotVec(ta.R(), pb) + ta.P();
    return rw::math::Transform3D<double>(p, r);
}

rw::math::Rotation3D<double> rotZ(double psi)
{
    const double c = std::cos(psi);
    const double s = std::sin(psi);
    return rw::math::Rotation3D<double>(c, -s, 0.0,
                                        s, c, 0.0,
                                        0.0, 0.0, 1.0);
}

rw::math::Rotation3D<double> rotX(double alpha)
{
    const double c = std::cos(alpha);
    const double s = std::sin(alpha);
    return rw::math::Rotation3D<double>(1.0, 0.0, 0.0,
                                        0.0, c, -s,
                                        0.0, s, c);
}

rw::math::Rotation3D<double> axisAngleRotation(const rw::math::Vector3D<double>& axis,
                                               double angle)
{
    const double c = std::cos(angle);
    const double s = std::sin(angle);
    const double t = 1.0 - c;
    const double kx = axis[0];
    const double ky = axis[1];
    const double kz = axis[2];
    return rw::math::Rotation3D<double>(
        c + t * kx * kx,      t * kx * ky - s * kz, t * kx * kz + s * ky,
        t * kx * ky + s * kz, c + t * ky * ky,      t * ky * kz - s * kx,
        t * kx * kz - s * ky, t * ky * kz + s * kx, c + t * kz * kz);
}

rw::math::Vector3D<double> rotateTranspose(const rw::math::Rotation3D<double>& r,
                                           const rw::math::Vector3D<double>& v)
{
    return rw::math::Vector3D<double>(
        r(0, 0) * v[0] + r(1, 0) * v[1] + r(2, 0) * v[2],
        r(0, 1) * v[0] + r(1, 1) * v[1] + r(2, 1) * v[2],
        r(0, 2) * v[0] + r(1, 2) * v[1] + r(2, 2) * v[2]);
}

rw::math::Rotation3D<double> rotateTransposeFrame(const rw::math::Rotation3D<double>& r,
                                                  const rw::math::Rotation3D<double>& rb)
{
    rw::math::Rotation3D<double> out;
    for (std::size_t i = 0; i < 3; ++i) {
        for (std::size_t j = 0; j < 3; ++j) {
            double s = 0.0;
            for (std::size_t k = 0; k < 3; ++k) { s += r(k, i) * rb(k, j); }
            out(i, j) = s;
        }
    }
    return out;
}

double rotationAngleBetween(const rw::math::Rotation3D<double>& ra,
                            const rw::math::Rotation3D<double>& rb)
{
    // Rrel = RAᵀ·RB（转置手工逐元素——Rotation3D::inverse 为外联符号面，
    // 冒烟纪律；正交阵逆＝转置）。
    rw::math::Rotation3D<double> rat;
    for (std::size_t i = 0; i < 3; ++i) {
        for (std::size_t j = 0; j < 3; ++j) {
            rat(i, j) = ra(j, i);
        }
    }
    const rw::math::Rotation3D<double> rel = rotMul(rat, rb);
    const double s = std::sqrt(
        (rel(2, 1) - rel(1, 2)) * (rel(2, 1) - rel(1, 2))
        + (rel(0, 2) - rel(2, 0)) * (rel(0, 2) - rel(2, 0))
        + (rel(1, 0) - rel(0, 1)) * (rel(1, 0) - rel(0, 1))) / 2.0;
    const double c = (rel(0, 0) + rel(1, 1) + rel(2, 2) - 1.0) / 2.0;
    return std::atan2(s, c);
}

rw::math::Transform3D<double> dhCoreTransform(double theta, double d)
{
    return rw::math::Transform3D<double>(rw::math::Vector3D<double>(0.0, 0.0, d),
                                         rotZ(theta));
}

rw::math::Transform3D<double> dhStaticSegment(double a, double alpha)
{
    return rw::math::Transform3D<double>(rw::math::Vector3D<double>(a, 0.0, 0.0),
                                         rotX(alpha));
}

rw::math::Transform3D<double> dhRebuildStep(const std::vector<double>& x,
                                            std::size_t j, std::size_t count)
{
    // 头部静段：上一关节的 a/α（x[4(j-1)+2]、x[4(j-1)+3]）；j=0 无头部
    // （S_{-1}＝恒等——基座侧不在 DH 参数内，§7.4）。
    rw::math::Transform3D<double> step = identityTransform();
    if (j > 0) {
        step = transformMul(step, dhStaticSegment(x[4 * (j - 1) + 2], x[4 * (j - 1) + 3]));
    }
    // 纯 z 螺旋核心（θ_offset 单独入几何，zeroOffset 不入——F-590 同步）。
    step = transformMul(step, dhCoreTransform(x[4 * j], x[4 * j + 1]));
    // 链尾静段：仅末关节携带本关节 a/α（中间关节的静段已作为下一关节
    // 头部落位——同一静段不重复入链）。
    if (j + 1 == count) {
        step = transformMul(step, dhStaticSegment(x[4 * j + 2], x[4 * j + 3]));
    }
    return step;
}

bool solveLinearSystem(std::vector<double> a, std::vector<double> b, std::size_t n,
                       double relativeTol, std::vector<double>& out)
{
    // 主元判据的绝对阈值＝系数矩阵最大绝对值×相对容差（确定性——比较序固定）。
    double maxAbs = 0.0;
    for (const double v : a) { maxAbs = std::max(maxAbs, std::abs(v)); }
    const double pivotTol = maxAbs * relativeTol;
    for (std::size_t col = 0; col < n; ++col) {
        // 部分主元：当前列在剩余行中选最大幅值行（确定性比较：严格大于才换序）。
        std::size_t pivot = col;
        double best = std::abs(a[col * n + col]);
        for (std::size_t row = col + 1; row < n; ++row) {
            const double v = std::abs(a[row * n + col]);
            if (v > best) {
                best = v;
                pivot = row;
            }
        }
        if (!(best > pivotTol)) { return false; }  // 近奇异——主元不足
        if (pivot != col) {
            for (std::size_t j = 0; j < n; ++j) { std::swap(a[col * n + j], a[pivot * n + j]); }
            std::swap(b[col], b[pivot]);
        }
        // 消元（固定运算序——行优先、逐列）。
        for (std::size_t row = col + 1; row < n; ++row) {
            const double factor = a[row * n + col] / a[col * n + col];
            if (factor == 0.0) { continue; }
            for (std::size_t j = col; j < n; ++j) { a[row * n + j] -= factor * a[col * n + j]; }
            b[row] -= factor * b[col];
        }
    }
    // 回代（列逆序固定）。
    out.assign(n, 0.0);
    for (std::size_t i = n; i-- > 0;) {
        double s = b[i];
        for (std::size_t j = i + 1; j < n; ++j) { s -= a[i * n + j] * out[j]; }
        out[i] = s / a[i * n + i];
    }
    return true;
}

std::vector<double> numericJacobian(const std::vector<double>& x,
                                    const SolverTargets& targets)
{
    const std::vector<double> r0 = residualOf(x, targets);
    const std::size_t m = r0.size();
    const std::size_t n = x.size();
    std::vector<double> j(m * n, 0.0);
    std::vector<double> xa = x;
    std::vector<double> xb = x;
    for (std::size_t jCol = 0; jCol < n; ++jCol) {
        xa = x;
        xb = x;
        const std::size_t coordinate = jCol % 4U;
        // 长度坐标以 1 mm 作为零附近的相对步长下限，而不是直接使用整条
        // 链的 positionScaleM；否则一个 2 mm 的 a 参数会被迫用 1 m 级步长，
        // 小参数的导数被截断误差淹没。大参数仍按自身幅值放大步长。
        const double referenceScale = (coordinate == 0U || coordinate == 3U)
                                          ? 1.0
                                          : std::max(kMinimumPositionScaleM,
                                                     std::abs(x[jCol]));
        const double h = kDerivativeRelativeStep
                       * std::max(referenceScale, std::abs(x[jCol]));
        xa[jCol] += h;
        xb[jCol] -= h;
        const std::vector<double> ra = residualOf(xa, targets);
        const std::vector<double> rb = residualOf(xb, targets);
        for (std::size_t iRow = 0; iRow < m; ++iRow) {
            j[iRow * n + jCol] = (ra[iRow] - rb[iRow]) / (2.0 * h);
        }
    }
    return j;
}

LmResult lmSolve(const SolverTargets& targets, std::vector<double> x0,
                 const std::vector<bool>& optimizable)
{
    const std::size_t n = x0.size();
    const std::size_t m = targets.size() * 6;

    if (!std::isfinite(targets.positionScaleM)
        || targets.positionScaleM > kMaximumPositionScaleM) {
        return {DhConvergenceState::Diverged, x0};
    }
    std::vector<double> r = residualOf(x0, targets);
    double cost = costOf(r);
    // 初值即非有限（1e200 级溢出样本——AnalysisFailed UT 边界）：LM 迭代
    // 无法在非有限代价面上进行，直接判发散（不产出参数——执行失败轴
    // TASK-02，非语义结论）。
    if (!std::isfinite(cost)) {
        return {DhConvergenceState::Diverged, x0};  // 初值即溢出——发散
    }

    double lambda = kLambdaInit;
    std::size_t stall = 0;
    for (std::size_t iter = 0; iter < kMaxIterations; ++iter) {
        // ---- 步 1：数值雅可比与正规方程系数（固定运算序）----
        const std::vector<double> j = numericJacobian(x0, targets);
        std::vector<double> jtj(n * n, 0.0);
        std::vector<double> jtr(n, 0.0);
        for (std::size_t iRow = 0; iRow < m; ++iRow) {
            for (std::size_t jc = 0; jc < n; ++jc) {
                const double v = j[iRow * n + jc];
                if (v == 0.0) { continue; }  // 稀疏跳零——值恒等，仅省乘法
                jtr[jc] += v * r[iRow];
                for (std::size_t kc = jc; kc < n; ++kc) {
                    jtj[jc * n + kc] += v * j[iRow * n + kc];
                }
            }
        }
        // 对称补全（上三角已累计——含自身转置项，确定性）。
        for (std::size_t jc = 0; jc < n; ++jc) {
            for (std::size_t kc = 0; kc < jc; ++kc) { jtj[jc * n + kc] = jtj[kc * n + jc]; }
        }
        // 有限性前置守卫：正规方程含 NaN/Inf（雅可比/残差溢出——数值
        // 失败形态之一）即终止为 Diverged（AnalysisFailed——MDL-10），
        // 绝不带非有限值进入求解（内层阻尼重试无界化的根源防线）。
        bool finiteSystem = true;
        for (std::size_t k = 0; finiteSystem && k < n; ++k) {
            finiteSystem = std::isfinite(jtr[k]) && std::isfinite(jtj[k * n + k]);
        }
        if (!finiteSystem) {
            return {DhConvergenceState::Diverged, x0};
        }
        // ---- 步 2：阻尼线搜索（λ 加速失败回退——有界尝试，确定性）----
        std::vector<double> delta;
        bool solved = false;
        for (std::size_t attempt = 0; attempt < kMaxDampingAttempts; ++attempt) {
            // LM 阻尼矩阵＝λ·diag(JᵀJ)（对角占优缩放；零对角元兜底 1——
            // 防全零行（钉住坐标列恒零）致奇异）。
            std::vector<double> damped = jtj;
            for (std::size_t k = 0; k < n; ++k) {
                const double diag = jtj[k * n + k];
                damped[k * n + k] = diag + lambda * (diag > 0.0 ? diag : 1.0);
            }
            std::vector<double> negJtr(n, 0.0);
            for (std::size_t k = 0; k < n; ++k) { negJtr[k] = -jtr[k]; }
            if (solveLinearSystem(std::move(damped), std::move(negJtr), n,
                                  kPivotRelativeTolerance, delta)) {
                solved = true;
                break;
            }
            lambda = std::min(lambda * 10.0, kLambdaMax);  // 奇异→加大阻尼重试
        }
        if (!solved) {
            return {DhConvergenceState::Diverged, x0};  // 线性求解反复失败——发散
        }
        // 步长有限性守卫（奇异系统的病态解——非有限步长＝发散）。
        for (std::size_t k = 0; k < n; ++k) {
            if (!std::isfinite(delta[k])) {
                return {DhConvergenceState::Diverged, x0};
            }
        }
        // ---- 步 3：候选步评估（接受/拒绝——固定判据）----
        std::vector<double> xNew = x0;
        double maxStep = 0.0;
        for (std::size_t k = 0; k < n; ++k) {
            if (!optimizable[k]) { continue; }  // 钉住坐标不动（字典序定值约束）
            xNew[k] += delta[k];
            maxStep = std::max(maxStep, std::abs(delta[k]));
        }
        if (!std::isfinite(costOf(residualOf(xNew, targets)))) {
            return {DhConvergenceState::Diverged, x0};  // 步进溢出——发散
        }
        const std::vector<double> rNew = residualOf(xNew, targets);
        const double costNew = costOf(rNew);
        if (!std::isfinite(costNew)) {
            return {DhConvergenceState::Diverged, x0};
        }
        if (costNew < cost) {
            // 接受：代价下降（严格比较——确定性）。
            x0 = std::move(xNew);
            r = std::move(rNew);
            cost = costNew;
            lambda = std::max(lambda / 10.0, kLambdaMin);
            stall = 0;
            if (maxStep <= kStepConvergenceBound || cost <= 0.0) {
                return {DhConvergenceState::Converged, x0};  // 步长收敛
            }
        } else {
            // 拒绝：加大阻尼收缩步长；连续停滞→数值极小点＝收敛。
            lambda = std::min(lambda * 10.0, kLambdaMax);
            if (++stall >= kStallLimit) {
                return {DhConvergenceState::Converged, x0};
            }
        }
    }
    // 迭代预算耗尽仍未触发收敛判据＝不收敛（MDL-10"不收敛/发散"族——
    // AnalysisFailed，不产出语义结论）。
    return {DhConvergenceState::Diverged, x0};
}

std::pair<std::size_t, std::vector<std::size_t>> rankAndFreeColumns(
    const std::vector<double>& jacobian, std::size_t m, std::size_t n)
{
    std::vector<double> a = jacobian;  // 消元工作副本
    double maxAbs = 0.0;
    for (const double v : a) { maxAbs = std::max(maxAbs, std::abs(v)); }
    const double pivotTol = maxAbs * kPivotRelativeTolerance;

    std::vector<std::size_t> freeColumns;
    std::size_t rank = 0;
    std::size_t nextRow = 0;
    for (std::size_t col = 0; col < n; ++col) {
        // 在剩余行中找该列最大主元（确定性——严格大于才换序）。
        std::size_t pivot = m;
        double best = pivotTol;  // 低于容差＝无主元→自由列
        for (std::size_t row = nextRow; row < m; ++row) {
            const double v = std::abs(a[row * n + col]);
            if (v > best) {
                best = v;
                pivot = row;
            }
        }
        if (pivot == m) {
            freeColumns.push_back(col);  // 该列无线性独立方向——自由
            continue;
        }
        if (pivot != nextRow) {
            for (std::size_t jc = 0; jc < n; ++jc) {
                std::swap(a[nextRow * n + jc], a[pivot * n + jc]);
            }
        }
        // 消去下方行对该列的分量（固定序）。
        for (std::size_t row = nextRow + 1; row < m; ++row) {
            const double factor = a[row * n + col] / a[nextRow * n + col];
            if (factor == 0.0) { continue; }
            for (std::size_t jc = col; jc < n; ++jc) {
                a[row * n + jc] -= factor * a[nextRow * n + jc];
            }
        }
        ++rank;
        ++nextRow;
    }
    return {rank, freeColumns};
}

InertiaTensor rotateInertia(const InertiaTensor& i, const rw::math::Rotation3D<double>& r)
{
    const double m[3][3] = {
        { i.ixx, i.ixy, i.ixz },
        { i.ixy, i.iyy, i.iyz },
        { i.ixz, i.iyz, i.izz },
    };
    double acc[3][3] = {};  // R·I
    for (int row = 0; row < 3; ++row) {
        for (int col = 0; col < 3; ++col) {
            double sum = 0.0;
            for (int k = 0; k < 3; ++k) {
                sum += r(row, k) * m[k][col];
            }
            acc[row][col] = sum;
        }
    }
    double out3[3][3] = {};  // (R·I)·Rᵀ
    for (int row = 0; row < 3; ++row) {
        for (int col = 0; col < 3; ++col) {
            double sum = 0.0;
            for (int k = 0; k < 3; ++k) {
                sum += acc[row][k] * r(col, k);  // Rᵀ(k,col)=R(col,k)
            }
            out3[row][col] = sum;
        }
    }
    InertiaTensor out;
    out.ixx = out3[0][0];
    out.iyy = out3[1][1];
    out.izz = out3[2][2];
    out.ixy = out3[0][1];
    out.ixz = out3[0][2];
    out.iyz = out3[1][2];
    return out;
}

generateSeededLhsCandidates(const OptimizationConfiguration& config)
{
    // 第 1 步：防御复验（种子 0 等在此拦截——生成器是种子的第一消费者）。
    validateConfiguration(config);

    // 第 2 步：采样维度集＝未锁定且授权的连续/量化/枚举绑定（§8.2 改型
    // "锁定集外扰动"；DiscreteDevice 属 R2 组合空间采样——不进 R1），
    // bindingId 字典序（确定性维度序）。
    std::vector<const VariableBinding*> dims;
    dims.reserve(config.variables.size());
    for (const auto& b : config.variables) {
        if (b.locked || !b.authorized) {
            continue;  // 锁定/未授权维度不采样（§5.4——出现在补丁即拒绝）
        }
        if (b.kind == VariableKind::Continuous || b.kind == VariableKind::Quantized
            || b.kind == VariableKind::Enumeration) {
            dims.push_back(&b);
        }
    }
    std::sort(dims.begin(), dims.end(),
              [](const VariableBinding* a, const VariableBinding* b) {
                  return a->bindingId < b->bindingId;
              });

    // 第 3 步：非基线候选数 n（预算上限——§8.2"生成器受 OptimizationBudget
    // 约束"；maxCandidates≥1 已校验，无下溢）。
    const std::uint32_t n = config.budget.maxCandidates - 1U;

    std::vector<CandidatePatch> patches;
    patches.reserve(static_cast<std::size_t>(n) + 1U);

    // 第 8 步（前置落位）：基线候选恒为批首元素（§8.2——基线总是生成并
    // 参与评估；空补丁有确定身份；label 不参与身份）。
    CandidatePatch baseline;
    baseline.label = "baseline";
    patches.push_back(std::move(baseline));

    if (n == 0U) {
        return patches;  // 预算＝仅基线——合法退化
    }

    // 第 4 步：自持 splitmix64（状态＝种子——同种子同输出，跨平台确定）。
    SplitMix64 rng;
    rng.state = config.seed;

    // 第 5 步：每维度独立的 n 层层序置换（Fisher-Yates，PRNG 驱动——
    // 拉丁超立方正交性：每维度 n 个候选各占一层，空间填充）。
    std::vector<std::vector<std::uint32_t>> perms(dims.size());
    for (std::size_t d = 0; d < dims.size(); ++d) {
        auto& perm = perms[d];
        perm.resize(n);
        for (std::uint32_t i = 0; i < n; ++i) {
            perm[i] = i;  // 恒等层序初值
        }
        // Fisher-Yates 自后向前洗牌（i>n 下界防护：n==0 时循环体不执行）。
        for (std::uint32_t i = n; i-- > 1U;) {
            // j ∈ [0, i]（模减偏置存在但量级 ≤2⁻³²相对——采样均匀性足够，
            // 确定性不受影响；精确无偏混洗非需求面）。
            const std::uint32_t j = static_cast<std::uint32_t>(rng.nextU64() % (i + 1U));
            std::swap(perm[i], perm[j]);
        }
    }

    // 第 6~7 步：逐候选逐维度取值并经 makeCandidatePatch 构造（补丁
    // canonical 唯一编码层——量化对齐/排序/规范化复用 T03 单点）。
    for (std::uint32_t i = 0; i < n; ++i) {
        std::vector<PatchItem> items;
        items.reserve(dims.size());
        for (std::size_t d = 0; d < dims.size(); ++d) {
            const VariableBinding& b = *dims[d];
            const std::uint32_t layer = perms[d][i];
            const double u = rng.nextUnit();  // 层内均匀位置 [0,1)
            PatchItem item;
            item.bindingId = b.bindingId;
            if (b.kind == VariableKind::Enumeration) {
                // 枚举维度：PRNG 均匀取封闭值域下标（clamp 末位防 u≈1 时
                // 越界——确定性；组合上限保护＝值域即词表封闭集）。
                const std::size_t domain = b.enumValues.size();
                if (domain == 0) {
                    // 空值域枚举绑定属研究定义非法（validateBindings 面）——
                    // 防御式拒绝，不静默跳过（fail-fast）。
                    throw OptimizationError(
                        kOptInputInvalid,
                        "OPT-INPUT-INVALID: 绑定 " + b.bindingId
                            + " 为空值域枚举（enumValues 空）——研究定义非法");
                }
                auto idx = static_cast<std::size_t>(
                    static_cast<double>(domain) * u);
                if (idx >= domain) {
                    idx = domain - 1U;  // u 上界钳制（u<1 时理论不可达——防御）
                }
                item.enumIndex = static_cast<std::uint32_t>(idx);
            } else if (b.kind == VariableKind::Quantized) {
                // 量化维度：采样域收缩为 [lower+step, upper−step]（对齐偏差
                // ≤step/2 ⇒ 对齐后必在界内——补丁构造器 round-half-even 后
                // 验界不拒绝）；收缩域为空（区间窄于两步）时退化为绑定
                // 默认值（采样设计的确定性退化——值仍是显式默认，非静默
                // 纠错）。
                const double lo = b.lowerBound + b.step;
                const double hi = b.upperBound - b.step;
                if (lo <= hi) {
                    item.scalarValue = lo + (static_cast<double>(layer) + u)
                            / static_cast<double>(n) * (hi - lo);
                } else {
                    item.scalarValue = b.defaultValue;
                }
            } else {
                // 连续维度：层 [layer/n,(layer+1)/n) 映射到 [lower,upper]
                // 层内均匀点（u<1 ⇒ 严格小于上界端点，含端点安全）。
                item.scalarValue
                    = b.lowerBound
                    + (static_cast<double>(layer) + u) / static_cast<double>(n)
                          * (b.upperBound - b.lowerBound);
            }
            items.push_back(std::move(item));
        }
        // 第 7 步：补丁构造（锁定拒绝不可能——采样域已排除；构造抛＝研究
        // 定义与词表值域矛盾〔如正性维度配负区间〕——fail-fast 传播）。
        CandidatePatch patch = makeCandidatePatch(
            config.variables, config.stage, items, "cand-" + std::to_string(i));
        patches.push_back(std::move(patch));
    }

    return patches;
}

JsonValue parseJson(std::string_view text)
{
    Parser p(text);
    return p.run();
}

std::string dumpJson(const JsonValue& value, bool pretty)
{
    if (!pretty) {
        std::string out;
        dumpValue(value, &out);
        return out;
    }
    // 简易 pretty 打印器：递归带深度。
    struct P {
        static void go(const JsonValue& v, int depth, std::string* o) {
            const auto nl = [&](int d) { o->push_back('\n'); o->append(static_cast<std::size_t>(d) * 2, ' '); };
            switch (v.kind) {
            case JsonValue::Kind::Null:   o->append("null"); break;
            case JsonValue::Kind::Bool:   o->append(v.boolean ? "true" : "false"); break;
            case JsonValue::Kind::Number: dumpNumber(v.number, o); break;
            case JsonValue::Kind::String: dumpEscaped(v.text, o); break;
            case JsonValue::Kind::Array:
                if (v.items.empty()) { o->append("[]"); break; }
                o->push_back('[');
                for (std::size_t i = 0; i < v.items.size(); ++i) {
                    if (i > 0) { o->push_back(','); }
                    nl(depth + 1);
                    go(v.items[i], depth + 1, o);
                }
                nl(depth);
                o->push_back(']');
                break;
            case JsonValue::Kind::Object:
                if (v.members.empty()) { o->append("{}"); break; }
                o->push_back('{');
                for (std::size_t i = 0; i < v.members.size(); ++i) {
                    if (i > 0) { o->push_back(','); }
                    nl(depth + 1);
                    dumpEscaped(v.members[i].first, o);
                    o->append(": ");
                    go(v.members[i].second, depth + 1, o);
                }
                nl(depth);
                o->push_back('}');
                break;
            default:
                throw TestKitError(TestKitErrorKind::Usage, "json-dump: 未知值类别（防御分支）");
            }
        }
    };
    // 人读形态：两空格缩进，对象键后 ": "。
    std::string out;
    P::go(value, 0, &out);
    return out;
}

rw::math::Transform3D<double> interpolateCartesianLine(
    const rw::math::Transform3D<double>& ta,
    const rw::math::Transform3D<double>& tb,
    double s)
{
    // 前置：行程参数 ∈[0,1]（越界外推属几何语义破坏——§8.2 定义域）。
    if (!(s >= 0.0 && s <= 1.0)) {
        throw TrajectoryError("trajectory/cartesian/interpolate-range",
                              "行程参数 s 须 ∈[0,1]，实际 " + std::to_string(s));
    }

    // 端点快速路径：s=0/1 直接返回端点位姿——保证端点**位级**精确还原
    // （V-04 断言依托；通用 slerp 公式在 s=0/1 时 sin(θ)/sinθ 的浮点除
    // 不保证精确等于 1/0，会有 1 ULP 级姿态漂移，违反端点还原义务）。
    if (s == 0.0) {
        return ta;
    }
    if (s == 1.0) {
        return tb;
    }

    // 位置：逐分量凸组合 p(s)=(1-s)·p_a+s·p_b——s=0/1 浮点下精确还原
    // 端点（V-04 端点还原断言依托；与 PTP 插值同式的笛卡尔侧对应）。
    const rw::math::Vector3D<double>& pa = ta.P();
    const rw::math::Vector3D<double>& pb = tb.P();
    const rw::math::Vector3D<double> p((1.0 - s) * pa[0] + s * pb[0],
                                       (1.0 - s) * pa[1] + s * pb[1],
                                       (1.0 - s) * pa[2] + s * pb[2]);

    // 姿态：四元数最短路径 slerp（§8.2"姿态最短弧 slerp（四元数最短
    // 路径）"）。手写显式实现以锁定口径（V-05 与显式四元数对照）：
    // 两端各取单位四元数→点积为负时翻转一端（±q 同旋转成对，取非负
    // 点积一支保证最短弧）→θ=acos(dot)→标准 slerp 公式。
    QuatComponents qa = normalizedQuat(ta.R());
    QuatComponents qb = normalizedQuat(tb.R());
    double dot = qa.x * qb.x + qa.y * qb.y + qa.z * qb.z + qa.w * qb.w;
    if (dot < 0.0) {
        // 最短路径翻转：q 与 -q 表示同一旋转，翻转后插值走短弧（V-05
        // 大弧样例锁定该分支——Rz(350°)→Rz(10°) 经 0° 而非绕行 340°）。
        qb.x = -qb.x;
        qb.y = -qb.y;
        qb.z = -qb.z;
        qb.w = -qb.w;
        dot = -dot;
    }
    const double theta = safeAcos(dot);
    QuatComponents qo = qa;
    if (theta > 1e-12) {
        // 常规 slerp：θ 大于极小角阈值——sin(θ) 远离 0，公式稳定。
        const double sinTheta = std::sin(theta);
        const double wa = std::sin((1.0 - s) * theta) / sinTheta;
        const double wb = std::sin(s * theta) / sinTheta;
        qo.x = wa * qa.x + wb * qb.x;
        qo.y = wa * qa.y + wb * qb.y;
        qo.z = wa * qa.z + wb * qb.z;
        qo.w = wa * qa.w + wb * qb.w;
    } else {
        // 近共线分支：θ<1e-12 rad（约 5.7×10⁻¹¹°）时 sin(θ)≈θ 数值不稳，
        // 回退线性插值后归一化（数学极限一致——θ→0 时 slerp→nlerp）。
        qo.x = (1.0 - s) * qa.x + s * qb.x;
        qo.y = (1.0 - s) * qa.y + s * qb.y;
        qo.z = (1.0 - s) * qa.z + s * qb.z;
        qo.w = (1.0 - s) * qa.w + s * qb.w;
        const double len = std::sqrt(qo.x * qo.x + qo.y * qo.y + qo.z * qo.z + qo.w * qo.w);
        if (len > 0.0) {
            const double inv = 1.0 / len;
            qo.x *= inv;
            qo.y *= inv;
            qo.z *= inv;
            qo.w *= inv;
        }
    }

    rw::math::Transform3D<double> out;
    out.P() = p;
    out.R() = rw::math::Quaternion<double>(qo.x, qo.y, qo.z, qo.w).toRotation3D();
    return out;
}

inline double hermiteH000(double t)
{
    return 1.0 + t * t * t * (-10.0 + t * (15.0 - 6.0 * t));
}

inline double hermiteH100(double t)
{
    return t + t * t * t * (-6.0 + t * (8.0 - 3.0 * t));
}

inline double hermiteH001(double t)
{
    const double t2 = t * t;
    return t2 * t * (10.0 + t * (-15.0 + 6.0 * t));
}

inline double hermiteH101(double t)
{
    const double t2 = t * t;
    return t2 * t * (-4.0 + t * (7.0 - 3.0 * t));
}

inline BasisValues basisH0000(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    BasisValues b;
    b.p = 1.0 - 10.0 * u3 + 15.0 * u2 * u2 - 6.0 * u3 * u2;
    b.d1 = -30.0 * u2 + 60.0 * u3 - 30.0 * u2 * u2;
    // 二阶导修正（WP-16-T14 批登记——T08 批遗留笔误）：d1 对 u 求导应为
    // −60u+180u²−120u³，原实现误写 −60u+120u²−60u³。既有黄金算例未暴露
    // 的原因：全部零起点（q0=0 → h0000 加权项为零）＋结点处各基 d2 端点
    // 值两版本同为 0（C² 守卫不敏感）；数值实验（中心差分对照解析）定位。
    // 修正后 h0000''+h0001'' 恒 0（值基和恒 1 的二阶导）恢复结构性成立。
    b.d2 = -60.0 * u + 180.0 * u2 - 120.0 * u3;
    // 三阶导（WP-16-T14 批）：d2 对 u 求导——常值 −60＋180·2u−120·3u²。
    b.d3 = -60.0 + 360.0 * u - 360.0 * u2;
    return b;
}

inline BasisValues basisH0010(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    BasisValues b;
    b.p = u - 6.0 * u3 + 8.0 * u2 * u2 - 3.0 * u3 * u2;
    b.d1 = 1.0 - 18.0 * u2 + 32.0 * u3 - 15.0 * u2 * u2;
    b.d2 = -36.0 * u + 96.0 * u2 - 60.0 * u3;
    // 三阶导（WP-16-T14 批增列）。
    b.d3 = -36.0 + 192.0 * u - 180.0 * u2;
    return b;
}

inline BasisValues basisH0001(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    BasisValues b;
    b.p = 10.0 * u3 - 15.0 * u2 * u2 + 6.0 * u3 * u2;
    b.d1 = 30.0 * u2 - 60.0 * u3 + 30.0 * u2 * u2;
    b.d2 = 60.0 * u - 180.0 * u2 + 120.0 * u3;
    // 三阶导（WP-16-T14 批增列）。
    b.d3 = 60.0 - 360.0 * u + 360.0 * u2;
    return b;
}

inline BasisValues basisH0011(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    BasisValues b;
    b.p = -4.0 * u3 + 7.0 * u2 * u2 - 3.0 * u3 * u2;
    b.d1 = -12.0 * u2 + 28.0 * u3 - 15.0 * u2 * u2;
    b.d2 = -24.0 * u + 84.0 * u2 - 60.0 * u3;
    // 三阶导（WP-16-T14 批增列）。
    b.d3 = -24.0 + 168.0 * u - 180.0 * u2;
    return b;
}

inline BasisValues septicS0(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    const double u4 = u2 * u2;
    const double u5 = u4 * u;
    const double u6 = u5 * u;
    BasisValues b;
    b.p = 1.0 - 35.0 * u4 + 84.0 * u5 - 70.0 * u6 + 20.0 * u5 * u2;
    b.d1 = -140.0 * u3 + 420.0 * u4 - 420.0 * u5 + 140.0 * u6;
    b.d2 = -420.0 * u2 + 1680.0 * u3 - 2100.0 * u4 + 840.0 * u5;
    b.d3 = -840.0 * u + 5040.0 * u2 - 8400.0 * u3 + 4200.0 * u4;
    return b;
}

inline BasisValues septicS1(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    const double u4 = u2 * u2;
    const double u5 = u4 * u;
    const double u6 = u5 * u;
    BasisValues b;
    b.p = u - 20.0 * u4 + 45.0 * u5 - 36.0 * u6 + 10.0 * u5 * u2;
    b.d1 = 1.0 - 80.0 * u3 + 225.0 * u4 - 216.0 * u5 + 70.0 * u6;
    b.d2 = -240.0 * u2 + 900.0 * u3 - 1080.0 * u4 + 420.0 * u5;
    b.d3 = -480.0 * u + 2700.0 * u2 - 4320.0 * u3 + 2100.0 * u4;
    return b;
}

inline BasisValues septicS2(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    const double u4 = u2 * u2;
    const double u5 = u4 * u;
    const double u6 = u5 * u;
    BasisValues b;
    b.p = 35.0 * u4 - 84.0 * u5 + 70.0 * u6 - 20.0 * u5 * u2;
    b.d1 = 140.0 * u3 - 420.0 * u4 + 420.0 * u5 - 140.0 * u6;
    b.d2 = 420.0 * u2 - 1680.0 * u3 + 2100.0 * u4 - 840.0 * u5;
    b.d3 = 840.0 * u - 5040.0 * u2 + 8400.0 * u3 - 4200.0 * u4;
    return b;
}

inline BasisValues septicS3(double u)
{
    const double u2 = u * u;
    const double u3 = u2 * u;
    const double u4 = u2 * u2;
    const double u5 = u4 * u;
    const double u6 = u5 * u;
    BasisValues b;
    b.p = -15.0 * u4 + 39.0 * u5 - 34.0 * u6 + 10.0 * u5 * u2;
    b.d1 = -60.0 * u3 + 195.0 * u4 - 204.0 * u5 + 70.0 * u6;
    // 二阶/三阶导（逐次求导：s3''＝−180u²+780u³−1020u⁴+420u⁵、
    // s3'''＝−360u+2340u²−4080u³+2100u⁴；端点校验 s3''(1)=0、
    // s3'''(1)=0——C³ 结构条件的基级前提，测试端点矩阵钉扎）。
    b.d2 = -180.0 * u2 + 780.0 * u3 - 1020.0 * u4 + 420.0 * u5;
    b.d3 = -360.0 * u + 2340.0 * u2 - 4080.0 * u3 + 2100.0 * u4;
    return b;
}
